syntax:
element { property: value; }
.class { property: value; }
#id { property: value; }
[parent] > child { property: value; }
ancestor descendant { property: value; }

@layer reset, components, overrides;
@layer components { .class { color: value; } }
.class { color: inherit; margin: initial; }

.parent { position: relative; }
.child { position: absolute; inset-block-start: length; inset-inline-end: length; }
.sticky { position: sticky; top: length; z-index: integer; }

.class:hover { property: value; }
.control:focus-visible { outline: width style color; }
input:checked + label { property: value; }
.item:nth-child(2n) { property: value; }

.class::before { content: "text"; }
.class::after { content: ""; display: block; }
input::placeholder { color: color; }
